namespace SmartProperty.Application.Abstractions.Storage;

/// <summary>
/// Where the bytes of legal documents (ownership deeds, authorizations, licenses) are kept. Private: nothing here is
/// ever reachable by a URL. Bytes leave only through an authorized API call that streams them after checking who asks.
/// </summary>
/// <remarks>
/// Kept apart from <see cref="IImageStorage"/> on purpose: a different root (volume or bucket), a different backup
/// policy, and no chance that a mistake in how photos are served exposes a deed. Keys are generated by the platform
/// (<c>quarantine/{requestId}/{versionId}.pdf</c> until scanned, <c>documents/...</c> once clean), never taken from a client.
/// </remarks>
public interface IPrivateDocumentStorage
{
    /// <summary>Stores the stream's remaining bytes under the key, replacing anything already there.</summary>
    Task SaveAsync(string key, Stream content, CancellationToken cancellationToken = default);

    /// <summary>Opens the stored file for reading, or returns null when there is none. The caller disposes it.</summary>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken = default);

    /// <summary>Deletes the file. A file that is not there is already deleted, so that is not an error.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken = default);
}
